const grid = document.querySelector('#grid');

const courses = [
  { title: '자바스크립트 입문', hours: 12 },
  { title: '리액트 시작하기', hours: 20 },
  { title: 'CSS 레이아웃 마스터', hours: 8 },
];

const cardOf = (course) => `
  <article class="course">
    <h3 class="course__title">${course.title}</h3>
    <p class="course__meta">${course.hours}시간</p>
  </article>
`;

const render = (list) => {
  grid.innerHTML = list.map(cardOf).join('');
};

console.log('비교 함수 없이:', [12, 20, 8].sort());
console.log('비교 함수와 함께:', [12, 20, 8].sort((a, b) => a - b));

console.log('정렬 전 첫 코스:', courses[0].title);

const sorted = courses.sort((a, b) => a.hours - b.hours);

console.log('정렬 후 첫 코스:', courses[0].title);
console.log('원본과 결과가 같은 배열인가:', courses === sorted);

render(sorted);

