steps.solutionCode:
const courses = [
  { title: '자바스크립트 입문', hours: 12 },
  { title: '리액트 시작하기', hours: 20 },
  { title: 'CSS 레이아웃 마스터', hours: 8 },
];

const grid = document.querySelector('#grid');

const cardOf = (course) => `
  <article class="course">
    <h3 class="course__title">${course.title}</h3>
    <p class="course__meta">${course.hours}시간</p>
  </article>
`;

const render = (list) => {
  grid.innerHTML = list.map(cardOf).join('');
};

render(courses);

document.querySelector('#asc').addEventListener('click', () => {
  render([...courses].sort((a, b) => a.hours - b.hours));
});

document.querySelector('#desc').addEventListener('click', () => {
  render([...courses].sort((a, b) => b.hours - a.hours));
});
